/* ===================== BÀI 26 · MOVS/STOS/LODS và DF ===================== */
/* Bài 26 · MOVS/STOS/LODS và DF (AMTS-EMB-002-M07-L02, X86-026) — sinh bởi tools/author/mpu8086/l26.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P26=[{"label": "Ví dụ: MOVSB từng byte với LOOP", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnguon   DB      'HELLO'\nN       EQU     $-nguon\ndich    DB      N DUP('.'), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX                  ; đích luôn là ES:DI\n        CLD                             ; DF = 0: SI, DI tăng\n        LEA     SI, nguon               ; nguồn DS:SI\n        LEA     DI, dich                ; đích ES:DI\n        MOV     CX, N\nCHEP:   MOVSB                           ; ES:[DI] <- DS:[SI], SI+1, DI+1\n        LOOP    CHEP\n        LEA     DX, dich\n        MOV     AH, 09H\n        INT     21H                     ; in HELLO\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước. Mỗi MOVSB (18 chu kỳ) chép một byte từ DS:SI sang ES:DI; nhìn SI và DI cùng tăng 1 ở phần Thanh ghi và byte được tô ở phần Bộ nhớ. Sau 5 lần, SI = 0005h, DI = 000Ah, màn hình in HELLO. Đoán trước: trước lần MOVSB thứ ba, DI bằng bao nhiêu? Đáp án 0007h."}, {"label": "Ví dụ: REP MOVSB và REP MOVSW", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnguon   DB      'ABCDEFGHIJKLMNOP'\nN       EQU     $-nguon                 ; 16 byte\ndich1   DB      N DUP(0)\ndich2   DB      N DUP(0)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     SI, nguon\n        LEA     DI, dich1\n        MOV     CX, N                   ; 16 lần 1 byte\n        REP     MOVSB                   ; 9 + 17 x 16 chu kỳ\n        LEA     SI, nguon\n        LEA     DI, dich2\n        MOV     CX, N/2                 ; 8 lần 1 word\n        REP     MOVSW                   ; 9 + 17 x 8 chu kỳ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai cách chép 16 byte. REP MOVSB lặp 16 lần: 9 + 17 × 16 = 281 chu kỳ. REP MOVSW với CX = N/2 = 8: 9 + 17 × 8 = 145 chu kỳ, vì mỗi lần chép 2 byte. Mỗi REP chạy trọn trong một bước; dich1, dich2 đều thành ABCD…P. Đoán trước: ngay trước REP MOVSW, CX bằng bao nhiêu? Đáp án 0008h."}, {"label": "Lỗi: quên nạp ES, chép vào PSP", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnguon   DB      'HELLO'\nN       EQU     $-nguon\ndich    DB      N DUP('.'), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        CLD                             ; LỖI: chưa nạp ES\n        LEA     SI, nguon\n        LEA     DI, dich\n        MOV     CX, N\n        REP     MOVSB                   ; ghi vào ES:DI, ES = PSP\n        LEA     DX, dich\n        MOV     AH, 09H\n        INT     21H                     ; dich vẫn là .....\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: không có MOV ES, AX. ES vẫn là đoạn PSP 0700h (giả định của trình mô phỏng) nên REP MOVSB ghi HELLO vào 0700:0005 … 0009 (chọn vùng ES ở phần Bộ nhớ để thấy), đè lên dữ liệu của DOS; dich vẫn là năm dấu chấm. Sửa: MOV ES, AX ngay sau MOV DS, AX. Đoán trước: ở lệnh REP MOVSB, ES bằng bao nhiêu? Đáp án 0700h."}, {"label": "Ví dụ: REP STOSB, STOSW điền vùng nhớ", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndong1   DB      20 DUP(?), 13, 10, '$'\ndong2   DB      20 DUP(?), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, dong1\n        MOV     AL, '*'\n        MOV     CX, 20\n        REP     STOSB                   ; 20 lần ghi AL\n        LEA     DI, dong2\n        MOV     AX, 3D2AH               ; AL = 2Ah '*', AH = 3Dh '='\n        MOV     CX, 10\n        REP     STOSW                   ; 10 lần ghi AX (2 byte)\n        LEA     DX, dong1\n        MOV     AH, 09H\n        INT     21H\n        LEA     DX, dong2\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "REP STOSB ghi AL = '*' vào 20 byte: 9 + 10 × 20 = 209 chu kỳ. REP STOSW ghi AX = 3D2Ah (byte thấp 2Ah = '*', byte cao 3Dh = '=') vào 10 word, nên dòng hai là *=*=…; dong2 bắt đầu ở độ lệch lẻ 0017h nên mỗi word tốn thêm 4 chu kỳ: 9 + 14 × 10 = 149. Đoán trước: sau REP STOSB, DI bằng bao nhiêu? Đáp án 0014h."}, {"label": "Ví dụ: LODSB/STOSB đổi chữ hoa tại chỗ", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'Mov ax, 5$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     SI, chuoi\n        MOV     DI, SI                  ; đọc và ghi cùng chỗ\nLAP:    LODSB                           ; AL <- DS:[SI], SI+1\n        CMP     AL, '$'\n        JE      XONG\n        CMP     AL, 'a'\n        JB      GHI\n        CMP     AL, 'z'\n        JA      GHI\n        SUB     AL, 20H                 ; chữ thường -> chữ hoa\nGHI:    STOSB                           ; ES:[DI] <- AL, DI+1\n        JMP     LAP\nXONG:   LEA     DX, chuoi\n        MOV     AH, 09H\n        INT     21H                     ; MOV AX, 5\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "LODSB đọc từng ký tự vào AL và tăng SI; chữ trong khoảng 'a' … 'z' bị trừ 20h; STOSB ghi lại vào cùng chỗ (DI = SI lúc đầu). Gặp '$' thì dừng và in MOV AX, 5. Xem từng byte của chuoi đổi trong phần Bộ nhớ. Đoán trước: với ký tự 'o', JB GHI có nhảy không? Đáp án không (6Fh ≥ 61h)."}, {"label": "Lỗi: thủ tục để lại DF = 1", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndau     DB      'wxyz'\nbuf     DB      'ABCDE'\ndich    DB      5 DUP('.'), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CALL    XOA                     ; buf = ABC**\n        LEA     SI, buf                 ; LỖI: không CLD, DF vẫn = 1\n        LEA     DI, dich\n        MOV     CX, 5\n        REP     MOVSB\n        LEA     DX, dich\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nXOA     PROC                            ; xóa 2 byte cuối của buf, đi lùi\n        LEA     DI, buf+4\n        MOV     CX, 2\n        MOV     AL, '*'\n        STD\n        REP     STOSB\n        RET                             ; quên CLD trước khi trở về\nXOA     ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: XOA dùng STD để ghi lùi rồi RET mà không CLD. REP MOVSB của chương trình chính vì thế đi ngược: chép buf[0] = 'A' rồi lùi vào vùng dau (z, y, x, w), đồng thời DI lùi vào buf, ghi đè buf thành Awxyz. Màn hình in A.... thay vì ABC**. Sửa: CLD trước RET trong XOA (hoặc CLD trước REP MOVSB). Đoán trước: ngay trước REP MOVSB, DF bằng mấy? Đáp án 1."}, {"label": "Ví dụ: STD và LODSB đọc ngược", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      '8086'\nN       EQU     $-chuoi\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        LEA     SI, chuoi+N-1           ; ký tự cuối\n        MOV     CX, N\n        STD                             ; DF = 1: SI giảm\nLAP:    LODSB                           ; AL <- [SI], SI-1\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        LOOP    LAP\n        CLD                             ; trả DF về 0 ngay sau khi dùng\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "STD làm LODSB giảm SI. SI bắt đầu ở ký tự cuối (chuoi + N − 1 = 0003h) nên in 6, 8, 0, 8. Sau vòng lặp SI = FFFFh (0 − 1). CLD trả DF về 0 ngay sau khi dùng xong. Đoán trước: sau LODSB đầu tiên, SI bằng bao nhiêu? Đáp án 0002h."}];
const sim26=makeX86Sim(document.getElementById("x86-l26"),{id:"s26",presets:P26,file:"BAI26.ASM"});
makeX86Ex(document.getElementById("ex-l26"),sim26,[{"t": "Điền ký tự bằng REP STOSB", "d": "Đọc một ký tự c rồi một chữ số n (0–9), đều bằng INT 21h hàm 01h (có hiện). Ghi c vào n byte đầu của buf (9 byte, ban đầu là dấu chấm) bằng REP STOSB, xuống dòng (CR, LF) rồi in buf bằng INT 21h hàm 09h. Ví dụ gõ #3 thì dòng thứ hai là ###...... (3 dấu # rồi 6 dấu chấm). Kết thúc bằng INT 21h hàm 4Ch. Code mẫu chạy được nhưng buf không đổi.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkytu    DB      ?\nbuf     DB      9 DUP('.'), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 01H                 ; ký tự điền (có hiện)\n        INT     21H\n        MOV     kytu, AL\n        MOV     AH, 01H                 ; số lượng 1..9\n        INT     21H\n        SUB     AL, '0'\n        MOV     CL, AL\n        MOV     CH, 0\n        MOV     AL, kytu\n        LEA     DI, buf\n        CLD                             ; TODO: STOSB ghi vào đâu?\n        REP     STOSB\n        MOV     AH, 02H                 ; xuống dòng\n        MOV     DL, 13\n        INT     21H\n        MOV     DL, 10\n        INT     21H\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "#3", "out": "#3\r\n###......"}, {"in": "A9", "out": "A9\r\nAAAAAAAAA"}, {"in": "x1", "out": "x1\r\nx........"}, {"in": "*0", "out": "*0\r\n........."}, {"in": "Z5", "out": "Z5\r\nZZZZZ...."}, {"in": "=7", "out": "=7\r\n=======.."}]}, {"t": "Sửa lỗi DF sau thủ tục", "d": "Chương trình đọc 6 phím vào buf, rồi phím thứ 7 là số k (0–6) (INT 21h hàm 08h). Thủ tục XOA ghi dấu * vào k byte cuối của buf bằng STD và REP STOSB. Sau đó chương trình chép buf sang dich bằng REP MOVSB và in dich. Ví dụ ABCDEF2 phải in ABCD**. Code mẫu in sai (A.....): tìm nguyên nhân và sửa. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      6 DUP(?)\ndich    DB      6 DUP('.'), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, buf                 ; đọc 6 phím vào buf\n        MOV     CX, 6\nDOC:    MOV     AH, 08H\n        INT     21H\n        STOSB\n        LOOP    DOC\n        MOV     AH, 08H                 ; phím thứ 7: số byte cần xóa (0..6)\n        INT     21H\n        SUB     AL, '0'\n        MOV     CL, AL\n        MOV     CH, 0\n        CALL    XOA                     ; xóa CX byte cuối của buf\n        LEA     SI, buf                 ; chép buf sang dich\n        LEA     DI, dich\n        MOV     CX, 6\n        REP     MOVSB\n        LEA     DX, dich\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nXOA     PROC                            ; CX = số byte; ghi '*' lùi từ cuối buf\n        LEA     DI, buf+5\n        MOV     AL, '*'\n        STD\n        REP     STOSB\n        RET\nXOA     ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDEF2", "out": "ABCD**"}, {"in": "ABCDEF0", "out": "ABCDEF"}, {"in": "ABCDEF6", "out": "******"}, {"in": "1234561", "out": "12345*"}, {"in": "xyzxyz3", "out": "xyz***"}, {"in": "a.b.c.5", "out": "a*****"}]}, {"t": "Chép n byte nhanh", "d": "Đọc hai chữ số n = 00 … 40 (INT 21h hàm 08h). Chép n byte đầu của chuỗi nguon (40 ký tự) vào đầu dich (40 dấu chấm) rồi in dich bằng INT 21h hàm 09h. Phần đọc số và in đã có. Code mẫu chép bằng MOVSB + LOOP: đúng nhưng chậm. Viết lại phần chép để chạy không quá 760 chu kỳ ở test chậm nhất và mã không quá 62 byte. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnguon   DB      'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd'\ndich    DB      40 DUP('.'), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        MOV     AH, 08H                 ; đọc 2 chữ số n = 00..40\n        INT     21H\n        SUB     AL, '0'\n        MOV     BL, 10\n        MUL     BL                      ; AX = chục x 10\n        MOV     BL, AL\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        ADD     AL, BL\n        MOV     CL, AL\n        MOV     CH, 0                   ; CX = n\n        CLD\n        LEA     SI, nguon\n        LEA     DI, dich\n        JCXZ    XONG                    ; n = 0: không chép gì\nCHEP:   MOVSB\n        LOOP    CHEP\nXONG:\n        LEA     DX, dich\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "40", "out": "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd"}, {"in": "39", "out": "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abc."}, {"in": "00", "out": "........................................"}, {"in": "01", "out": "A......................................."}, {"in": "02", "out": "AB......................................"}, {"in": "17", "out": "ABCDEFGHIJKLMNOPQ......................."}, {"in": "20", "out": "ABCDEFGHIJKLMNOPQRST...................."}], "perf": {"cycles": 760, "bytes": 62}}]);

makeQuiz("quiz26","score26",[{"q": "DF = 0, SI = 0100h, DI = 0200h, CX = 3. Sau <code>REP MOVSW<\/code>, SI, DI, CX bằng bao nhiêu?", "o": ["SI = 0103h, DI = 0203h, CX = 0", "SI = 0106h, DI = 0206h, CX = 3", "SI = 00FAh, DI = 01FAh, CX = 0", "SI = 0106h, DI = 0206h, CX = 0"], "a": 3, "e": "REP lặp 3 lần, mỗi lần chép 1 word và cộng 2 vào SI, DI (DF = 0), CX giảm về 0. Cộng 1 là của MOVSB; trừ là khi DF = 1."}, {"q": "Đoạn code sau ghi dấu # vào những byte nào của <code>buf DB 5 DUP('.')<\/code>?<pre class=\"mp-asm\">        STD\n        LEA     DI, buf+3\n        MOV     AL, '#'\n        MOV     CX, 2\n        REP     STOSB\n        CLD<\/pre>", "o": ["buf[3] và buf[4]; sau đó DI = buf+5", "buf[2] và buf[1]; sau đó DI = buf", "Chỉ buf[3], vì STD làm REP dừng sau 1 lần", "buf[3] và buf[2]; sau đó DI = buf+1"], "a": 3, "e": "DF = 1 nên STOSB ghi ở DI rồi trừ 1: ghi buf+3, buf+2; DI cuối = buf+1. REP vẫn lặp đủ CX lần dù DF bằng mấy."}, {"q": "Trong <code>MOVSB<\/code>, phần nào đổi được đoạn bằng tiền tố?", "o": ["Chỉ đích (mặc định ES:DI); nguồn luôn là DS:SI", "Cả nguồn và đích, mỗi bên một tiền tố riêng", "Chỉ nguồn (mặc định DS:SI); đích luôn là ES:DI", "Không bên nào; MOVSB không nhận tiền tố đoạn"], "a": 2, "e": "Tiền tố đoạn chỉ thay đoạn của toán hạng nguồn (DS). Đích của MOVS, STOS (và toán hạng ES:DI của CMPS, SCAS) cố định là ES."}, {"q": "CX = 0 khi chạy hai đoạn sau. Phát biểu nào đúng?<pre class=\"mp-asm\">; (1)          ; (2)\nREP MOVSB      L: MOVSB\n               LOOP L<\/pre>", "o": ["(1) không chép byte nào; (2) chép 65 536 byte", "Cả hai đều không chép byte nào", "(1) chép 65 536 byte; (2) không chép byte nào", "Cả hai đều chép đúng 1 byte rồi dừng"], "a": 0, "e": "REP kiểm CX ≠ 0 trước lần đầu nên với CX = 0 không làm gì (9 chu kỳ). LOOP giảm CX trước rồi mới kiểm: 0 − 1 = FFFFh, vòng chạy 65 536 lần. Cần JCXZ trước vòng LOOP."}, {"q": "Chương trình .EXE bắt đầu bằng <code>MOV AX, @DATA<\/code> / <code>MOV DS, AX<\/code> rồi dùng <code>REP STOSB<\/code> với <code>LEA DI, buf<\/code>. Byte được ghi vào đâu?", "o": ["Vào buf, vì STOSB dùng DS như mọi lệnh ghi bộ nhớ", "Vào đoạn PSP, cùng độ lệch với buf, vì ES chưa được nạp", "Vào đoạn ngăn xếp, vì DI mặc định đi với SS", "Không đâu cả: STOSB báo lỗi khi ES khác DS"], "a": 1, "e": "STOSB ghi vào ES:DI. Với chương trình .EXE, DOS (và trình mô phỏng) đặt ES = PSP lúc bắt đầu; phải MOV ES, AX (Ví dụ 3). CPU không kiểm tra ES."}]);

